        private void SetupDateEdit(DevExpress.XtraEditors.DateEdit edit)
        {
            edit.Properties.DisplayFormat.FormatString = "dd MMM yyyy";
            edit.Properties.DisplayFormat.FormatType = DevExpress.Utils.FormatType.DateTime;
            edit.Properties.EditFormat.FormatString = "dd MMM yyyy";
            edit.Properties.EditFormat.FormatType = DevExpress.Utils.FormatType.DateTime;
            edit.Properties.Mask.EditMask = "dd MMM yyyy";
            edit.Properties.Mask.UseMaskAsDisplayFormat = true;
        }

        private void SetupLookUp(DevExpress.XtraEditors.LookUpEdit edit)
        {
            edit.Properties.NullText = "";
            edit.Properties.ShowHeader = false;
            edit.Properties.ShowFooter = false;
            edit.Properties.TextEditStyle = DevExpress.XtraEditors.Controls.TextEditStyles.Standard;
        }

        private void SetTotalTextEdit(DevExpress.XtraEditors.TextEdit edit)
        {
            edit.Properties.ReadOnly = true;
            edit.Properties.CharacterCasing = System.Windows.Forms.CharacterCasing.Upper;
            edit.Properties.Appearance.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Far;
        }

        private DevExpress.XtraLayout.LayoutControlItem AddItem(DevExpress.XtraLayout.LayoutControlGroup group, string text, System.Windows.Forms.Control control, int width)
        {
            var item = group.AddItem(text, control);
            item.TextVisible = !string.IsNullOrEmpty(text);
            item.MinSize = new System.Drawing.Size(width, 24);
            item.MaxSize = new System.Drawing.Size(width, 0);
            item.SizeConstraintsType = DevExpress.XtraLayout.SizeConstraintsType.Custom;
            return item;
        }

